import React, { useEffect } from 'react';
import { MemoryRouter, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { Provider } from 'react-redux';
import { store } from './store/store';
import { AppLayout } from './components/layout/AppLayout';
import {
  SimpleNotFoundPage,
  SimpleForbiddenPage,
  ERR_SESSION_KEY,
  registerApiNavigationHandler,
  unregisterApiNavigationHandler,
} from '@linm-soft-org/linm-web-common-components';
import { isStandalone, showDevNav } from './dev/isStandalone';
import { StandaloneMockNav } from './standalone/StandaloneMockNav';
import { MemoryRouterSync } from './router/MemoryRouterSync';
import { navigateInAppPath } from './router/navigateInAppPath';
import { getBrowserRouterPath } from './routing/routerPaths';
import type { IRootProps } from './types/IRootProps';
import pageSuspenseStyles from './components/layout/PageSuspense.module.css';

const DevPage = React.lazy(() => import('./dev/DevPage'));

// ── Dashboard ──────────────────────────────────────────────────────────────
const DashboardPage = React.lazy(() => import('./pages/dashboard/DashboardPage'));

// ── Báo Cáo (baocao) ─────────────────────────────────────────────────────
const BaoCaoBanHangPage      = React.lazy(() => import('./pages/baocao/BaoCaoBanHangPage'));
const BaoCaoMuaHangPage      = React.lazy(() => import('./pages/baocao/BaoCaoMuaHangPage'));
const BaoCaoNxtPage          = React.lazy(() => import('./pages/baocao/BaoCaoNxtPage'));
const BaoCaoTonKhoCuPage     = React.lazy(() => import('./pages/baocao/BaoCaoTonKhoCuPage'));
const BaoCaoDoanhThuPage     = React.lazy(() => import('./pages/baocao/BaoCaoDoanhThuPage'));
const BaoCaoThuChiPage       = React.lazy(() => import('./pages/baocao/BaoCaoThuChiPage'));
const SoQuyPage              = React.lazy(() => import('./pages/baocao/SoQuyPage'));
const SoQuyNgayPage          = React.lazy(() => import('./pages/baocao/SoQuyNgayPage'));
const SoNhatKyThuTienPage    = React.lazy(() => import('./pages/baocao/SoNhatKyThuTienPage'));
const SoChiTietPage          = React.lazy(() => import('./pages/baocao/SoChiTietPage'));
const SoChiTietTatCaTkPage   = React.lazy(() => import('./pages/baocao/SoChiTietTatCaTkPage'));
const SoTongHopChuTTatCaTkPage = React.lazy(() => import('./pages/baocao/SoTongHopChuTTatCaTkPage'));
const SoTongHopChuTPage      = React.lazy(() => import('./pages/baocao/SoTongHopChuTPage'));
const CanDoiPsTheoNgayPage   = React.lazy(() => import('./pages/baocao/CanDoiPsTheoNgayPage'));
const CanDoiPsTieuKhoanPage  = React.lazy(() => import('./pages/baocao/CanDoiPsTieuKhoanPage'));
const SoDuQuyNganHangPage    = React.lazy(() => import('./pages/baocao/SoDuQuyNganHangPage'));
const BangKeChungTuPage      = React.lazy(() => import('./pages/baocao/BangKeChungTuPage'));
const BaoCaoChiPhiPage       = React.lazy(() => import('./pages/baocao/BaoCaoChiPhiPage'));
const BaoCaoTaiChinhPage     = React.lazy(() => import('./pages/baocao/BaoCaoTaiChinhPage'));
const BaoCaoLuongPage        = React.lazy(() => import('./pages/baocao/BaoCaoLuongPage'));
const BaoCaoTscdPage         = React.lazy(() => import('./pages/baocao/BaoCaoTscdPage'));
const BaoCaoCcdcPage         = React.lazy(() => import('./pages/baocao/BaoCaoCcdcPage'));
const BaoCaoSpLoiPage        = React.lazy(() => import('./pages/baocao/BaoCaoSpLoiPage'));
const BangKeVatMuaPage       = React.lazy(() => import('./pages/baocao/BangKeVatMuaPage'));
const BangKeVatBanPage       = React.lazy(() => import('./pages/baocao/BangKeVatBanPage'));
const NhatKyChungTuPage      = React.lazy(() => import('./pages/baocao/NhatKyChungTuPage'));
const PhanTichPage           = React.lazy(() => import('./pages/baocao/PhanTichPage'));
const B01DnPage              = React.lazy(() => import('./pages/baocao/B01DnPage'));
const B02DnPage              = React.lazy(() => import('./pages/baocao/B02DnPage'));
const B03DnPage              = React.lazy(() => import('./pages/baocao/B03DnPage'));

const PageSuspense = ({ children }: { children: React.ReactNode }) => (
  <React.Suspense fallback={<div className={pageSuspenseStyles.fallback}>Đang tải...</div>}>
    {children}
  </React.Suspense>
);

const AppShell = () => (
  <>
    {isStandalone && <StandaloneMockNav />}
    <AppLayout />
  </>
);

/** Registers global API 403 navigator — chỉ GET (load page). */
const ApiErrorHandler: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const navigate = useNavigate();
  useEffect(() => {
    registerApiNavigationHandler((event) => {
      if (event.method !== 'GET') return;
      // 404: không navigate not-found — để toast / inline error
      if (event.statusCode !== 403) return;
      try {
        sessionStorage.setItem(
          ERR_SESSION_KEY,
          window.location.pathname + window.location.search,
        );
      } catch { /* noop */ }
      navigateInAppPath('/forbidden', navigate, { replace: true });
    });
    return () => unregisterApiNavigationHandler();
  }, [navigate]);
  return <>{children}</>;
};

const Root: React.FC<Partial<IRootProps>> = (_rootProps = {}) => (
  <Provider store={store}>
    <MemoryRouter
      initialEntries={[getBrowserRouterPath()]}
      future={{ v7_startTransition: true, v7_relativeSplatPath: true }}
    >
      <ApiErrorHandler>
        <MemoryRouterSync />
        <Routes>
            <Route path="/" element={isStandalone ? <AppShell /> : <AppLayout />}>
              {showDevNav && (
                <>
                  <Route index element={<Navigate to="/dev" replace />} />
                  <Route path="dev" element={<PageSuspense><DevPage /></PageSuspense>} />
                </>
              )}

              {/* API error routes */}
              <Route path="not-found" element={<SimpleNotFoundPage showDevNav={showDevNav} homePath="/baocao/tong-quan" />} />
              <Route path="forbidden" element={<SimpleForbiddenPage showDevNav={showDevNav} homePath="/baocao/tong-quan" />} />

              <Route path="baocao/tong-quan" element={<PageSuspense><DashboardPage /></PageSuspense>} />
            <Route path="dashboard" element={<Navigate to="/baocao/tong-quan" replace />} />

            <Route path="baocao" element={<Navigate to="baocao/ban-hang" replace />} />
            <Route path="baocao/ban-hang"       element={<PageSuspense><BaoCaoBanHangPage /></PageSuspense>} />
            <Route path="baocao/mua-hang"       element={<PageSuspense><BaoCaoMuaHangPage /></PageSuspense>} />
            {/*
              Báo cáo Công nợ và Sổ cái đã chuyển về domain MFE (Finance)
              qua mountType=parcel. Route redirect giữ cho backward compat.
            */}
            <Route path="baocao/cong-no" element={<Navigate to="/kt/cong-no" replace />} />
            <Route path="baocao/nxt"            element={<PageSuspense><BaoCaoNxtPage /></PageSuspense>} />
            <Route path="baocao/ton-kho-cu"     element={<PageSuspense><BaoCaoTonKhoCuPage /></PageSuspense>} />
            <Route path="baocao/doanh-thu"      element={<PageSuspense><BaoCaoDoanhThuPage /></PageSuspense>} />
            <Route path="baocao/thu-chi"        element={<PageSuspense><BaoCaoThuChiPage /></PageSuspense>} />
            <Route path="baocao/so-quy"         element={<PageSuspense><SoQuyPage /></PageSuspense>} />
            <Route path="baocao/so-quy-ngay"    element={<PageSuspense><SoQuyNgayPage /></PageSuspense>} />
            <Route path="baocao/so-nhat-ky-thu-tien" element={<PageSuspense><SoNhatKyThuTienPage /></PageSuspense>} />
            <Route path="baocao/so-chi-tiet"    element={<PageSuspense><SoChiTietPage /></PageSuspense>} />
            <Route path="baocao/so-chi-tiet-tat-ca-tk" element={<PageSuspense><SoChiTietTatCaTkPage /></PageSuspense>} />
            <Route path="baocao/so-tong-hop-chu-t-tat-ca-tk" element={<PageSuspense><SoTongHopChuTTatCaTkPage /></PageSuspense>} />
            <Route path="baocao/so-tong-hop-chu-t" element={<PageSuspense><SoTongHopChuTPage /></PageSuspense>} />
            <Route path="baocao/can-doi-ps-theo-ngay" element={<PageSuspense><CanDoiPsTheoNgayPage /></PageSuspense>} />
            <Route path="baocao/can-doi-ps-tieu-khoan" element={<PageSuspense><CanDoiPsTieuKhoanPage /></PageSuspense>} />
            <Route path="baocao/so-du-quy-ngan-hang" element={<PageSuspense><SoDuQuyNganHangPage /></PageSuspense>} />
            <Route path="baocao/bang-ke-chung-tu" element={<PageSuspense><BangKeChungTuPage /></PageSuspense>} />
            <Route path="baocao/chi-phi"        element={<PageSuspense><BaoCaoChiPhiPage /></PageSuspense>} />
            <Route path="baocao/tai-chinh"      element={<PageSuspense><BaoCaoTaiChinhPage /></PageSuspense>} />
            <Route path="baocao/luong"          element={<PageSuspense><BaoCaoLuongPage /></PageSuspense>} />
            <Route path="baocao/tscd"           element={<PageSuspense><BaoCaoTscdPage /></PageSuspense>} />
            <Route path="baocao/ccdc"           element={<PageSuspense><BaoCaoCcdcPage /></PageSuspense>} />
            <Route path="baocao/sp-loi"         element={<PageSuspense><BaoCaoSpLoiPage /></PageSuspense>} />
            <Route path="baocao/bang-ke-vat-mua" element={<PageSuspense><BangKeVatMuaPage /></PageSuspense>} />
            <Route path="baocao/bang-ke-vat-ban" element={<PageSuspense><BangKeVatBanPage /></PageSuspense>} />
            <Route path="baocao/nhat-ky-chung-tu" element={<PageSuspense><NhatKyChungTuPage /></PageSuspense>} />
            {/*
              Sổ cái — đã chuyển về Finance MFE qua mountType=parcel.
              Route redirect giữ cho backward compat.
            */}
            <Route path="baocao/so-cai" element={<Navigate to="/kt/so-cai" replace />} />
            <Route path="baocao/phan-tich"      element={<PageSuspense><PhanTichPage /></PageSuspense>} />
            <Route path="baocao/b01-dn"         element={<PageSuspense><B01DnPage /></PageSuspense>} />
            <Route path="baocao/b02-dn"         element={<PageSuspense><B02DnPage /></PageSuspense>} />
            <Route path="baocao/b03-dn"         element={<PageSuspense><B03DnPage /></PageSuspense>} />

            <Route path="*" element={<SimpleNotFoundPage showDevNav={showDevNav} homePath="/baocao/tong-quan" />} />
          </Route>
      </Routes>
      </ApiErrorHandler>
    </MemoryRouter>
  </Provider>
);

export default Root;
